#include <vector>
#include <cmath>
using namespace std;

class Solution {
public:
    int largestConsecutivePrimeSum(int n) {
        vector<bool> sieve(n + 1, true);
        sieve[0] = sieve[1] = false;
        for (int p = 2; p * p <= n; p++) {
            if (sieve[p]) {
                for (int m = p * p; m <= n; m += p) sieve[m] = false;
            }
        }
        vector<int> primes;
        for (int p = 2; p <= n; p++) if (sieve[p]) primes.push_back(p);
        int num_primes = primes.size();
        vector<long long> pref(num_primes + 1, 0);
        for (int i = 0; i < num_primes; i++) pref[i + 1] = pref[i] + primes[i];

        for (int len = num_primes; len >= 1; len--) {
            for (int start = 0; start <= num_primes - len; start++) {
                long long cur_sum = pref[start + len] - pref[start];
                if (cur_sum > n) break;
                if (sieve[cur_sum]) return cur_sum;
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int largestConsecutivePrimeSum(int n) {
        boolean[] sieve = new boolean[n + 1];
        Arrays.fill(sieve, true);
        sieve[0] = sieve[1] = false;
        for (int p = 2; p * p <= n; p++) {
            if (sieve[p]) {
                for (int m = p * p; m <= n; m += p) sieve[m] = false;
            }
        }
        List<Integer> primes = new ArrayList<>();
        for (int p = 2; p <= n; p++) if (sieve[p]) primes.add(p);
        int numPrimes = primes.size();
        long[] pref = new long[numPrimes + 1];
        for (int i = 0; i < numPrimes; i++) pref[i + 1] = pref[i] + primes.get(i);

        for (int len = numPrimes; len >= 1; len--) {
            for (int start = 0; start <= numPrimes - len; start++) {
                long curSum = pref[start + len] - pref[start];
                if (curSum > n) break;
                if (sieve[(int)curSum]) return (int)curSum;
            }
        }
        return -1;
    }
}

var largestConsecutivePrimeSum = function(n) {
    const sieve = new Uint8Array(n + 1).fill(1);
    sieve[0] = sieve[1] = 0;
    for (let p = 2; p * p <= n; p++) {
        if (sieve[p]) {
            for (let m = p * p; m <= n; m += p) sieve[m] = 0;
        }
    }
    const primes = [];
    for (let p = 2; p <= n; p++) if (sieve[p]) primes.push(p);
    const pref = [0];
    for (const p of primes) pref.push(pref[pref.length - 1] + p);

    for (let len = primes.length; len >= 1; len--) {
        for (let start = 0; start <= primes.length - len; start++) {
            const curSum = pref[start + len] - pref[start];
            if (curSum > n) break;
            if (sieve[curSum]) return curSum;
        }
    }
    return -1;
};
